lPass):?><button class="btn secondary small copy-secret" type="button">Copy</button><?php endif;?></div></div></section></div><?php endif;?><?php if($r['notes']):?><section class="cart-card"><h2>Service Notes</h2><p><?=nl2br(e($r['notes']))?></p></section><?php endif;?></main><script>(function(){document.querySelectorAll('.reveal-secret').forEach(function(b){b.addEventListener('click',function(){var i=b.parentElement.querySelector('input');var show=i.type==='password';i.type=show?'text':'password';b.textContent=show?'Hide':'Show';});});document.querySelectorAll('.copy-value').forEach(function(b){b.addEventListener('click',function(){navigator.clipboard.writeText(b.dataset.copy||'').then(function(){var old=b.textContent;b.textContent='Copied';setTimeout(function(){b.textContent=old},1200);});});});document.querySelectorAll('.copy-secret').forEach(function(b){b.addEventListener('click',function(){var i=b.parentElement.querySelector('input');navigator.clipboard.writeText(i.value).then(function(){var old=b.textContent;b.textContent='Copied';setTimeout(function(){b.textContent=old},1200);});});});})();</script><?php require __DIR__.'/includes/footer.php';?></body></html>
